using System.ComponentModel;
using System.Drawing;
namespace Bai4_16;
public class PriceTick{public DateTime Time{get;set;}public decimal Price{get;set;}public string Change{get;set;}="";}
public class Form1:Form
{
 Button start=new(),pause=new();Label priceLabel=new();DataGridView grid=new();ToolStripStatusLabel last=new(),count=new();BindingList<PriceTick> history=new();BindingSource bs=new();CancellationTokenSource cts;Task monitorTask;decimal lastPrice=65000m;int updates=0;readonly Random random=new();
 public Form1(){Text="Bài 4.16 - Crypto Stock Ticker";Width=950;Height=650;MinimumSize=new Size(700,450);var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(10),ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);
 var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true};start.Text="Bắt đầu Giám sát";start.AutoSize=true;pause.Text="Tạm dừng";pause.AutoSize=true;pause.Enabled=false;buttons.Controls.AddRange(new Control[]{start,pause});root.Controls.Add(buttons,0,0);
 priceLabel.Text="BTC/USD: $65,000.00";priceLabel.AutoSize=true;priceLabel.Font=new Font("Segoe UI",24,FontStyle.Bold);priceLabel.ForeColor=Color.DimGray;root.Controls.Add(priceLabel,0,1);
 grid.Dock=DockStyle.Fill;grid.AutoGenerateColumns=false;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Thời gian",DataPropertyName="Time",Width=180,DefaultCellStyle=new DataGridViewCellStyle{Format="HH:mm:ss"}});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="BTC/USD",DataPropertyName="Price",Width=180,DefaultCellStyle=new DataGridViewCellStyle{Format="N2"}});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Biến động",DataPropertyName="Change",Width=150});root.Controls.Add(grid,0,2);bs.DataSource=history;grid.DataSource=bs;
 var strip=new StatusStrip();last.Text="Lần cập nhật cuối: --:--:--";count.Text="Số lượt đồng bộ: 0";strip.Items.AddRange(new ToolStripItem[]{last,new ToolStripStatusLabel{Spring=true},count});Controls.Add(strip);start.Click+=(_,_)=>StartMonitor();pause.Click+=(_,_)=>PauseMonitor();FormClosing+=(_,_)=>cts?.Cancel();}
 void StartMonitor(){if(monitorTask!=null&&!monitorTask.IsCompleted)return;cts?.Dispose();cts=new();var token=cts.Token;start.Enabled=false;pause.Enabled=true;monitorTask=Task.Run(async()=>{try{while(true){await Task.Delay(2000,token).ConfigureAwait(false);decimal old=lastPrice;decimal next=old+(decimal)(random.NextDouble()*500-250);if(next<=0)next=old;lastPrice=next;var tick=new PriceTick{Time=DateTime.Now,Price=next,Change=next>=old?"Tăng":"Giảm"};if(IsDisposed||!IsHandleCreated)break;if(InvokeRequired){try{Invoke(new Action(()=>ApplyTick(tick)));}catch(ObjectDisposedException){break;}catch(InvalidOperationException){break;}}else ApplyTick(tick);}}catch(OperationCanceledException){}finally{if(!IsDisposed&&IsHandleCreated)try{BeginInvoke(new Action(()=>{start.Enabled=true;pause.Enabled=false;}));}catch{}}});}
 void ApplyTick(PriceTick t){priceLabel.Text="BTC/USD: $"+t.Price.ToString("N2");priceLabel.ForeColor=t.Change=="Tăng"?Color.ForestGreen:Color.Firebrick;history.Insert(0,t);while(history.Count>200)history.RemoveAt(history.Count-1);updates++;last.Text="Lần cập nhật cuối: "+t.Time.ToString("HH:mm:ss");count.Text="Số lượt đồng bộ: "+updates;}
 void PauseMonitor(){cts?.Cancel();pause.Enabled=false;last.Text="Đã yêu cầu tạm dừng...";}
}
